sp_widget.client_script:
api.controller = function ($scope) {
  /* widget controller */
  var c = this;

  $scope.handleClick = function (hackathon_id) {
    // Handle click event
    window.location.href =
      "/hck?id=ticket&sys_id=" +
      hackathon_id +
      "&table=x_1097288_hacktaho_hackathon_registration";
    // You can add more logic here, like navigating to a different page or opening a modal
  };
};

sp_widget.css:
/* Container styling */
.container {
  padding: 20px;
}

/* Card base styling */

.card {
  border-radius: 4px;
  border: 1px solid #dde2e6;
  box-shadow: none;
  background: #fff;
  height: 100%;
  padding: 20px 24px 0 24px;
  transition: none;
  width: 500px;
  min-width: 280px;
  max-width: 100%;
  word-break: break-word;
  overflow-wrap: break-word;
}

/* Remove hover effect */
.card:hover {
  transform: none;
  box-shadow: none;
}

/* Card title */

.card-title {
  font-size: 2rem;
  font-weight: 600;
  color: #181818;
  margin-bottom: 0.4rem;
  word-break: break-word;
  overflow-wrap: break-word;
}

/* Card text */

.card-text {
  font-size: 1.25rem;
  color: #555;
  margin-bottom: 0;
  word-break: break-word;
  overflow-wrap: break-word;
  padding-bottom: 2rem;
}

/* Details section */

.card-details {
  border-top: 2px solid #e3e6e8;
  background: #f7f7f7;
  padding: 16px 20px;
  font-size: 1.05rem;
  color: #555;
  border-radius: 0 0 4px 4px;
  word-break: break-word;
  overflow-wrap: break-word;
  margin-left: -24px;
  margin-right: -24px;
}

.row {
  display: flex;
  flex-wrap: wrap;
  row-gap: 40px;
}

/* Responsive tweaks */
@media (max-width: 768px) {
  .card {
    margin-bottom: 15px;
  }
}

sp_widget.script:
(function () {
  /* populate the 'data' object */
  /* e.g., data.table = $sp.getValue('table'); */
  data.hackathons = [];

  var gr = new GlideRecord("x_1097288_hacktaho_hackathon_registration"); // or whatever sort field you have
  gr.query();

  while (gr.next()) {
    data.hackathons.push({
      hackathonName: gr.getValue("hackathon_name"),
      description: gr.getValue("description"),
      startDate: gr.getValue("start_date"),
      hackathonMode: gr.getValue("mode"),
      id: gr.getUniqueValue(),
    });
  }
})();
